-- Server-only application schema. Supabase identities are verified by the API.
create schema mathroom;
revoke all on schema mathroom from public, anon, authenticated;
create table mathroom.users(id integer generated by default as identity primary key,auth_id uuid unique references auth.users(id),email text not null unique,username text not null unique,name text not null,role text not null check(role in ('admin','student')),active integer not null default 1 check(active in (0,1)),must_change integer not null default 0 check(must_change in (0,1)),created_at text not null);
create unique index one_tutor on mathroom.users(role) where role='admin';
create table mathroom.sessions(token_hash text primary key,user_id integer not null references mathroom.users(id) on delete cascade,expires_at bigint not null);
create index sessions_user on mathroom.sessions(user_id);
create table mathroom.login_limits(key text primary key,count integer not null,until_at bigint not null);
create table mathroom.chapters(id integer generated by default as identity primary key,number integer unique not null check(number between 1 and 9999),title text not null,description text not null default '');
create table mathroom.enrollments(student_id integer references mathroom.users(id),chapter_id integer references mathroom.chapters(id),primary key(student_id,chapter_id));
create index enrollments_chapter on mathroom.enrollments(chapter_id);
create table mathroom.lessons(id integer generated by default as identity primary key,student_id integer not null references mathroom.users(id),chapter_id integer not null references mathroom.chapters(id),title text not null,starts_at text not null,duration integer not null check(duration between 15 and 240),status text not null default 'scheduled' check(status in ('scheduled','completed','cancelled')),summary text not null default '',performance text not null default 'Not reviewed',comment text not null default '');
create index lessons_student_date on mathroom.lessons(student_id,starts_at);
create index lessons_chapter on mathroom.lessons(chapter_id);
create table mathroom.assignments(id integer generated by default as identity primary key,title text not null,chapter_id integer references mathroom.chapters(id),due_at text,status text not null default 'draft' check(status in ('draft','published')),questions text not null,base_dir text not null default '.',warnings text not null default '[]');
create index assignments_chapter on mathroom.assignments(chapter_id);
create table mathroom.assignment_students(assignment_id integer references mathroom.assignments(id),student_id integer references mathroom.users(id),primary key(assignment_id,student_id));
create index assignment_students_student on mathroom.assignment_students(student_id);
create table mathroom.assignment_assets(id integer generated by default as identity primary key,assignment_id integer not null references mathroom.assignments(id),path text not null,mime text not null,data text not null);
create index assets_assignment on mathroom.assignment_assets(assignment_id);
create table mathroom.responses(assignment_id integer references mathroom.assignments(id),student_id integer references mathroom.users(id),question_index integer not null,attempt integer not null check(attempt between 1 and 2),answers text,submitted_at text not null,score real check(score>=0),feedback text not null default '',primary key(assignment_id,student_id,question_index));
create index responses_student on mathroom.responses(student_id);
create table mathroom.response_photos(id integer generated by default as identity primary key,assignment_id integer not null references mathroom.assignments(id),student_id integer not null references mathroom.users(id),question_index integer not null default -1,mime text not null,data text not null);
create index photos_assignment_student on mathroom.response_photos(assignment_id,student_id);
create index photos_student on mathroom.response_photos(student_id);
create table mathroom.storage_cleanup(path text primary key,created_at timestamptz not null default now());
do $$ declare t record; begin
 for t in select tablename from pg_tables where schemaname='mathroom' loop
  execute format('alter table mathroom.%I enable row level security',t.tablename);
  execute format('revoke all on mathroom.%I from public,anon,authenticated',t.tablename);
 end loop;
end $$;
revoke all on all sequences in schema mathroom from public,anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('mathroom-private','mathroom-private',false,10485760,array['image/png','image/jpeg','image/webp']);
